(function(){tinymce.PluginManager.requireLangPack('insertcaptivate');tinymce.create('tinymce.plugins.insertcaptivatePlugin',{init:function(ed,url){ed.addCommand('mceinsertcaptivate',function(){ed.windowManager.open({file:url+'/dialog.php',width:320+parseInt(ed.getLang('insertcaptivate.delta_width',0)),height:120+parseInt(ed.getLang('insertcaptivate.delta_height',0)),inline:1},{plugin_url:url,some_custom_arg:'custom arg'})});ed.addButton('insertcaptivate',{title:'insertcaptivate.desc',cmd:'mceinsertcaptivate',image:url+'/img/captivate.gif'});ed.onNodeChange.add(function(ed,cm,n){cm.setActive('insertcaptivate',n.nodeName=='IMG')})},createControl:function(n,cm){return null},getInfo:function(){return{longname:'insertcaptivate plugin',author:'Some author',authorurl:'http://tinymce.moxiecode.com',infourl:'http://wiki.moxiecode.com/index.php/TinyMCE:Plugins/insertcaptivate',version:"1.0"}}});tinymce.PluginManager.add('insertcaptivate',tinymce.plugins.insertcaptivatePlugin)})();